    {"id":6,"name":"Molecular Spectroscopy","module":"molecular_spectroscopy","function":"analyze_molecular_spectrum","execution_contract":{"schema_version":"1.0","execution_level":"analysis_pipeline","completeness":"complete","input_specs":[{"name":"wavelength_nm","unit":"nm","description":"Finite, positive, strictly increasing calibrated wavelength samples; at least five points.","required":True},{"name":"intensity","unit":"detector units or calibrated spectral intensity","description":"Finite measured spectral intensity matching wavelength_nm.","required":True},{"name":"reference_bandheads","unit":"list of (nm,label)","description":"Optional user-supplied reference bandhead wavelengths and labels; not a built-in molecular database.","required":False},{"name":"prominence_fraction","unit":"dimensionless","description":"Peak prominence threshold relative to spectral contrast, in (0,1].","required":False},{"name":"baseline_quantile","unit":"dimensionless","description":"Constant baseline quantile in [0,0.5).","required":False},{"name":"band_ranges_nm","unit":"list of wavelength ranges","description":"Optional integration windows within the measured wavelength range.","required":False}],"output_specs":[{"name":"baseline","unit":"intensity","description":"Constant quantile baseline estimate."},{"name":"peaks","unit":"structured","description":"Detected feature wavelengths, intensities, prominence, approximate FWHM and optional nearest reference candidates."},{"name":"integrated_signal_intensity_nm","unit":"intensity nm","description":"Baseline-subtracted integrated signal; not power unless intensity is calibrated accordingly."},{"name":"band_integrals","unit":"intensity nm","description":"Optional baseline-subtracted integrals over user-selected wavelength windows."},{"name":"custom_model_fit","unit":"structured","description":"Optional separately callable user-defined model fit with parameters, covariance, residuals and fit diagnostics."}],"assumptions":["Wavelength calibration and any detector-response correction are handled by the caller.","The constant quantile baseline and local peak detection are exploratory feature extraction, not a species-specific molecular inversion.","Reference bandheads are supplied by the user and are not treated as confirmed identifications."],"preprocessing":["Validate finite matching one-dimensional arrays, positive strictly increasing wavelengths, prominence/baseline settings, reference entries, and in-range integration windows."],"algorithm":"Estimate a constant quantile baseline; detect peaks by prominence; estimate approximate widths at half prominence; integrate positive baseline-subtracted signal; optionally integrate requested wavelength windows and compare peaks to caller-supplied bandhead references. A separate callable fits user-defined physical or empirical molecular spectral models.","uncertainty_model":"No complete measurement uncertainty is inferred by the feature-summary workflow. User-defined curve fitting returns local covariance-based parameter uncertainties; these do not include calibration, model discrepancy, parameter degeneracy, or instrument-response uncertainties.","limitations":["Does not automatically identify molecular species or infer rotational/vibrational temperature, molecular density, or electron/ion temperature.","Overlapping bands, blends, wavelength-dependent response, noise, continuum emission and baseline choice can bias detected peaks and integrals.","Nearest reference matches are candidates only and require authoritative molecular constants/line lists and a user-selected tolerance.","Quantitative molecular temperature requires a validated species-specific model, transition data, instrument line-shape/response treatment and a defensible uncertainty budget.","Fit quality does not validate physical model suitability; independent experimental validation remains required."],"function_links":["tokamak_analysis.molecular_spectroscopy.analyze_molecular_spectrum"],"raw_data_to_physics":False,"workflow_modes":[{"name":"spectrum_feature_summary","function":"analyze_molecular_spectrum","inputs":["wavelength_nm (nm)","intensity (detector or calibrated units)","optional user reference bandheads","optional integration ranges"],"outputs":["baseline","detected peaks","approximate widths","integrated signal","optional reference candidates and band integrals"],"scope":"Exploratory molecular-spectrum feature extraction; not species or temperature inversion."},{"name":"user_defined_molecular_model_fit","function":"fit_custom_molecular_model","inputs":["wavelength_nm","intensity","model callable","parameter names","initial values","optional bounds and intensity uncertainties"],"outputs":["fitted parameters","covariance-based uncertainties","fitted spectrum","residuals","optional chi-square metrics"],"scope":"Fits only the model supplied by the user; model physics and parameter interpretation remain the user's responsibility."}]}},
